00165 void LocalStorage::set_device_id(uint16_t device_id, bool force) {
00166   if((force || (device_id != _device_id)) && device_id >= 5000 && device_id < 6000) {
00167     if(_memory.begin(memory_name)) {
00168       _device_id = device_id;
00169       _memory.putUShort(key_device_id, _device_id);
00170       _memory.end();
00171     } else {
00172       M5_LOGD("unable to save new value for device_id");
00173     }
00174   }
00175 }
00176 
00177 void LocalStorage::set_ap_password(const char* ap_password, bool force) {
