00386 bool LocalStorage::activate(bool) {
00387   _memory.begin(memory_name, true);
00388   _device_id = _memory.getUShort(key_device_id, D_DEVICE_ID);
00389   _alert_threshold = _memory.getUInt(key_alert_threshold, D_ALARM_THRESHOLD);
00390   _cpm_usvh = _memory.getBool(key_cpm_usvh, D_CPM_USVH);
00391   _manual_logging = _memory.getBool(key_manual_logging, D_MANUAL_LOGGING);
00392   _enable_journal = _memory.getBool(key_enable_journal, D_ENABLE_JOURNAL);
00393   _log_void = _memory.getBool(key_log_void, D_LOG_VOID);
00394   _screen_dim_timeout = _memory.getUInt(key_screen_dim_timeout, D_SCREEN_DIM_TIMEOUT);
00395   _screen_off_timeout = _memory.getUInt(key_screen_off_timeout, D_SCREEN_OFF_TIMEOUT);
00396   _animated_screensaver = _memory.getBool(key_animated_screensaver, D_ANIMATED_SCREENSAVER);
00397   if(_memory.getString(key_ap_password, _ap_password, CONFIG_VAL_MAX) == 0) {
00398     strcpy(_ap_password, D_AP_PASSWORD);
00399   }
00400   if(_memory.getString(key_wifi_ssid, _wifi_ssid, CONFIG_VAL_MAX) == 0) {
00401     strcpy(_wifi_ssid, D_WIFI_SSID);
00402   }
00403   if(_memory.getString(key_wifi_password, _wifi_password, CONFIG_VAL_MAX) == 0) {
00404     strcpy(_wifi_password, D_WIFI_PASSWORD);
00405   }
00406   if(_memory.getString(key_api_key, _api_key, CONFIG_VAL_MAX) == 0) {
00407     strcpy(_api_key, D_API_KEY);
00408   }
00409   _fixed_longitude = _memory.getDouble(key_fixed_longitude, D_FIXED_LONGITUDE);
00410   _fixed_latitude = _memory.getDouble(key_fixed_latitude, D_FIXED_LATITUDE);
00411   _fixed_range = _memory.getFloat(key_fixed_range, D_FIXED_RANGE);
00412   _dop_max = _memory.getUInt(key_dop_max, D_DOP_MAX);
00413   _last_longitude = _memory.getDouble(key_last_longitude, D_LAST_LONGITUDE);
00414   _last_latitude = _memory.getDouble(key_last_latitude, D_LAST_LATITUDE);
00415   _last_mode = static_cast<OperationalMode>(_memory.getUShort(key_last_mode, e_operational_mode_drive));
00416   _memory.end();
00417   return true;
00418 }
00419 
00420 int8_t LocalStorage::produce_data(const worker_map_t& workers) {
00421   // Get reading data to store
00422   const auto& gps = (GpsConnector*) workers.at(k_worker_gps_connector);
00423   if(gps->is_fresh() && gps->get_data().location_valid) {
00424     set_last_latitude(gps->get_data().latitude, false);
00425     set_last_longitude(gps->get_data().longitude, false);
00426     return Worker::e_worker_data_read;
00427   }
00428   return Worker::e_worker_idle;
00429 }
